package com.agentscope.codewiki.agent;

import java.util.Arrays;
import java.util.Optional;

/** Canonical repository wiki pages generated by CodeWiki. */
public enum WikiPage {
    OVERVIEW("overview.md"),
    ARCHITECTURE("architecture.md"),
    MODULES("modules.md"),
    DATAFLOW("dataflow.md"),
    REVIEW("review.md");

    private final String fileName;

    WikiPage(String fileName) {
        this.fileName = fileName;
    }

    public String getFileName() {
        return fileName;
    }

    public static Optional<WikiPage> fromFileName(String fileName) {
        return Arrays.stream(values()).filter(page -> page.fileName.equals(fileName)).findFirst();
    }

    public static Optional<WikiPage> fromInput(String value) {
        if (value == null || value.isBlank()) {
            return Optional.empty();
        }
        String normalized = value.trim().toLowerCase().replace('_', '-');
        return Arrays.stream(values())
                .filter(page -> page.fileName.equals(normalized))
                .findFirst()
                .or(
                        () ->
                                Arrays.stream(values())
                                        .filter(
                                                page ->
                                                        page.name()
                                                                .toLowerCase()
                                                                .replace('_', '-')
                                                                .equals(normalized))
                                        .findFirst());
    }
}
